const screen=document.body.dataset.demoScreen;const next={index:'profile',profile:'hub',hub:'quest',quest:'result',result:'hub'};const go=name=>location.href=name+'.html';
function toast(text){const box=document.querySelector('#demo-toast');box.textContent=text;box.hidden=false;setTimeout(()=>box.hidden=true,2800);}
document.addEventListener('click',event=>{if(event.target.closest('#portfolio-demo-bar'))return;const target=event.target.closest('a,button');if(!target)return;const text=(target.innerText||'').trim().toLowerCase();if(target.tagName==='A'&&target.getAttribute('href')?.startsWith('https://'))return;event.preventDefault();event.stopImmediatePropagation();if(/privacy|terms|legal|treaty|protocol|support|уведомлен|notification/.test(text)){toast('Демонстрационный макет: данные и аккаунты не отправляются на сервер.');return;}if(/vault|archive|галере|leaderboard/.test(text)){go('result');return;}if(/hub|кабинет/.test(text)){go('hub');return;}if(/profile|профиль/.test(text)){go('profile');return;}if(/radar|explore|match|квест|мисси/.test(text)&&screen!=='quest'){go('quest');return;}if(target.tagName==='BUTTON'||/нач|start|join|sign|приключ|откры|play|next|далее|continue|погна/.test(text)){go(next[screen]||'hub');return;}if(/date quest/.test(text)){go('index');return;}toast('Переходы между основными экранами доступны в панели демонстрации внизу.');},true);
document.addEventListener('submit',event=>{event.preventDefault();go(next[screen]||'hub');});
